{
  "qid": "t2i-0010-01",
  "sample_id": "0010",
  "gen_prompt": "老北京春节庙会的小吃摊前，木桌上一只大盘堆满咯吱盒，其中两三块被掰开、开口朝向镜头，盘子旁边放着一小碟椒盐；背景是虚化的红灯笼与熙攘人群，暖色光线，美食特写摄影。",
  "invocation": "L2",
  "knowledge_dim": "饮食文化——京味传统小吃的形态与制作特征（食物类世界知识）",
  "fidelity_checks": [
    {
      "check": "咯吱盒成品必须呈油炸小件形态：薄饼切成的小块或小卷（含切段卷），不得是整张未切的大薄饼或面团状整体",
      "anchor": {"type": "direct", "constraint_refs": ["1"], "derivation_chain": ""},
      "rubric": {"tier_0": "呈整张未切的大薄饼，或完全不成小件形态（如一整个面团/馒头状）", "tier_1": "总体为小件但形态含糊（难以分辨是小块还是小卷），或画面中混有少量整张大饼区域", "tier_2": "全部为适合一手拿取的小件：薄饼切成的小块或小卷（含切段卷），形态明确"},
      "variants_used": "覆盖清单全部变体：块状与卷状均落入满分档",
      "visibility_requirement": "主体为特写，形态必然可见，无不可见情形",
      "weight": 1.0
    },
    {
      "check": "咯吱盒外皮必须呈油炸形成的金黄至黄褐色泽",
      "anchor": {"type": "direct", "constraint_refs": ["2"], "derivation_chain": ""},
      "rubric": {"tier_0": "外皮呈苍白生面色，或焦黑、明显异色（红/绿等）等严重偏离油炸色泽", "tier_1": "整体偏浅黄或深浅斑驳不均，油炸色泽不够到位", "tier_2": "外皮整体呈金黄至黄褐色的油炸色泽，深浅过渡自然"},
      "variants_used": "无变体",
      "visibility_requirement": "外皮色泽在特写下必然可见，无不可见情形",
      "weight": 1.0
    },
    {
      "check": "咯吱盒外皮必须呈油炸后的酥脆质感：表面干爽酥松、可见炸制气泡或酥层",
      "anchor": {"type": "direct", "constraint_refs": ["3"], "derivation_chain": ""},
      "rubric": {"tier_0": "外皮光滑密实，呈蒸制面团或生面饼质感，完全无炸制气泡、酥层等油炸特征", "tier_1": "外皮干爽但质感细节不足，气泡或酥层隐约难辨，油炸特征不够明确", "tier_2": "外皮干爽酥松，清晰可见炸制形成的气泡孔或层叠酥皮结构，油炸质感真实"},
      "variants_used": "无变体",
      "visibility_requirement": "特写镜头下外皮质感应可见；若整体分辨率导致微观气泡不可辨，按及格档（有干爽感即可）处理",
      "weight": 1.0
    },
    {
      "check": "掰开块的内里必须呈绿豆面特有的黄绿色至豆黄色调，并与外皮油炸色泽形成内外层次；不得为小麦白面的纯白色",
      "anchor": {"type": "combination", "constraint_refs": ["2", "4"], "derivation_chain": ""},
      "rubric": {"tier_0": "可见断面/开口的内里呈纯白色（小麦白面感），或灰黑等明显错误色泽", "tier_1": "内里可见黄色调但含糊：与外皮色泽几乎同色难分层次，或黄中偏白、豆面特征不明显", "tier_2": "掰开块的内里清晰呈现黄绿色至豆黄色调，与外皮的油炸色泽形成可辨认的内外层次"},
      "variants_used": "无变体",
      "visibility_requirement": "题面已要求两三块掰开且开口朝向镜头；若画面完全无任何断面可见，本条按不适用处理（该显式规定未执行由文本一致性维度扣分，不在知识维度重复惩罚）",
      "weight": 1.0
    },
    {
      "check": "咯吱盒不得呈现为浸泡在汤汁中或水煮、烩制等带汤湿软的形态",
      "anchor": {"type": "direct", "constraint_refs": ["5"], "derivation_chain": ""},
      "rubric": {"tier_0": "咯吱盒浸泡在汤汁中，或呈水煮/烩制的湿软塌陷形态（如带汤碗装、浇汁盖浇）", "tier_1": "无汤汁但整体质感湿软发黏、塌陷失去挺立感，介于干爽油炸与湿煮之间难以判定", "tier_2": "全部为干爽挺立的油炸干食形态，装盘干爽，无任何汤汁、浇汁或湿软感"},
      "variants_used": "无变体",
      "visibility_requirement": "整体盛放形态可见即可判，无不可见情形",
      "weight": 1.0
    },
    {
      "check": "咯吱盒不得呈现为包裹明显馅料（肉馅/菜馅/豆沙馅等）的带馅点心形态",
      "anchor": {"type": "direct", "constraint_refs": ["6"], "derivation_chain": ""},
      "rubric": {"tier_0": "呈明显带馅点心形态：块体包裹大块肉馅/菜馅/豆沙等馅料，断面或开口处馅料外露且占比显著", "tier_1": "夹层处偶见深色薄层但未形成明显馅料包裹，整体仍以多层饼皮为主，难以判定为带馅点心", "tier_2": "通体为纯饼体（可有多层饼皮叠合），无任何明显馅料包裹或外露"},
      "variants_used": "无变体",
      "visibility_requirement": "以可见断面与外露表面判断；若画面无任何断面，则依据外表面判断：外表面无馅料外露即记满分档（内部无法核验不扣分）",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "画面主体是堆满大盘的咯吱盒，食物占据画面主导地位（特写构图）",
      "facet": "subject_prominence",
      "rubric": {"tier_0": "咯吱盒缺失、占比很小，或被背景人群/灯笼抢占主体地位", "tier_1": "咯吱盒可见但主体地位不突出，与背景元素体量相当", "tier_2": "咯吱盒堆满大盘、占据画面中心与大部分面积，为明确的视觉焦点"}
    },
    {
      "check": "其中两三块被掰开、开口朝向镜头，其余块保持完整",
      "facet": "difference_similarity",
      "rubric": {"tier_0": "无任何掰开的块（全部完整），或全部碎裂无完整块", "tier_1": "有掰开的块但开口朝向背离镜头或被遮挡，或掰开数量过多难以分辨『两三块』", "tier_2": "可清晰看到两三块掰开的块、开口朝向镜头，其余块保持完整"}
    },
    {
      "check": "一小碟椒盐摆放在咯吱盒盘旁的同一桌面上",
      "facet": "spatial_2d",
      "rubric": {"tier_0": "无椒盐碟，或椒盐碟压在食物上、悬空等位置关系错误", "tier_1": "有小碟但内容物不可辨，或位置关系含糊（如远角处难以确认与盘的相邻关系）", "tier_2": "咯吱盒盘旁的桌面上有一只可辨认的椒盐小碟（粉末状调料可见）"}
    },
    {
      "check": "场景为庙会小吃摊：木桌承载食物，背景为虚化的红灯笼与熙攘人群",
      "facet": "real_world_scene",
      "rubric": {"tier_0": "场景完全不符（如现代超市、无场景白底、家庭厨房等）", "tier_1": "有桌面与部分场景元素但庙会特征不全（如有灯笼无人群、背景未虚化但元素在）", "tier_2": "木桌、虚化的红灯笼与人群背景齐备，庙会小吃摊场景成立"}
    }
  ],
  "quality_facets": ["material_texture", "naturalness", "edge_clarity", "noise"],
  "aesthetic_facets": ["composition", "lighting_atmosphere", "style_control"],
  "leak_check": {
    "对照表": [
      {"constraint_ref": "1", "题面中是否出现": "无"},
      {"constraint_ref": "2", "题面中是否出现": "无"},
      {"constraint_ref": "3", "题面中是否出现": "无"},
      {"constraint_ref": "4", "题面中是否出现": "无"},
      {"constraint_ref": "5", "题面中是否出现": "无"},
      {"constraint_ref": "6", "题面中是否出现": "无"}
    ],
    "结论": "全为无"
  },
  "notes": "题面仅以『掰开、开口朝向镜头』规定动作与朝向，未涉及内里颜色、原料与外皮色泽等知识答案，[4] 的泄漏对照为无。样本图中的深色夹层、文字水印、白色勺具与油锅均为该图的偶然画法，未转化为任何判分标准，题面也未要求这些元素。若模型未画出掰开块，A3 在一致性维度扣分，F4 按不适用处理，避免知识维度与一致性维度重复惩罚。"
}
